import pandas as pd


def _is_null(x):
    try:
        return pd.isna(x)
    except (TypeError, ValueError):
        return x is None


def _not_equal(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _find_input(inputs: dict, *candidates):
    """Case-insensitive / whitespace-insensitive lookup of an input frame."""
    if inputs is None:
        return None
    # exact match first
    for c in candidates:
        if c in inputs:
            return inputs[c]
    # case-insensitive match
    lower_map = {str(k).strip().lower(): k for k in inputs.keys()}
    for c in candidates:
        key = lower_map.get(c.strip().lower())
        if key is not None:
            return inputs[key]
    return None


def run(inputs: dict) -> dict:
    dim_acct = _find_input(inputs, "DIM_ACCT", "dim_acct", "DimAcct")
    stg_acct = _find_input(inputs, "STG_ACCT", "stg_acct", "StgAcct")

    dim_cols = ["acct_id", "email", "tier", "eff_start_date", "eff_end_date", "is_current"]
    if dim_acct is None:
        dim_acct = pd.DataFrame(columns=dim_cols)
    else:
        dim_acct = dim_acct.copy()
        # ensure all expected columns exist
        for col in dim_cols:
            if col not in dim_acct.columns:
                dim_acct[col] = pd.NA

    stg_cols = ["acct_id", "email", "tier", "update_date"]
    if stg_acct is None or len(stg_acct) == 0:
        stg_acct = pd.DataFrame(columns=stg_cols)
    else:
        stg_acct = stg_acct.copy()
        for col in stg_cols:
            if col not in stg_acct.columns:
                stg_acct[col] = pd.NA

    # ---------------------------------------------------------------
    # Step 1: Dedup STG_ACCT to latest per acct_id by update_date.
    # Ties: greater (email, tier) lexicographic pair wins.
    # ---------------------------------------------------------------
    if len(stg_acct) > 0:
        stg_acct["_email_key"] = stg_acct["email"].fillna("")
        stg_acct["_tier_key"] = stg_acct["tier"].fillna("")
        stg_sorted = stg_acct.sort_values(
            by=["acct_id", "update_date", "_email_key", "_tier_key"],
            kind="mergesort",
        )
        dedup = stg_sorted.groupby("acct_id", as_index=False, sort=False).tail(1)
        dedup = dedup.drop(columns=["_email_key", "_tier_key"])
    else:
        dedup = stg_acct.copy()

    # ---------------------------------------------------------------
    # Step 2: Process each staged record against DIM_ACCT.
    # Maintain rows as a mutable list of dicts for in-place history edits.
    # ---------------------------------------------------------------
    rows = dim_acct.to_dict("records")

    # Normalize existing rows' is_current to plain python values for safe compare
    for r in rows:
        if "is_current" in r and not _is_null(r["is_current"]):
            try:
                r["is_current"] = int(r["is_current"])
            except (TypeError, ValueError):
                pass

    for _, s in dedup.iterrows():
        acct_id = s["acct_id"]
        s_email = s["email"]
        s_tier = s["tier"]
        s_update_date = s["update_date"]

        # find current row index for this acct_id
        current_idx = None
        for idx, r in enumerate(rows):
            if r.get("acct_id") == acct_id and not _is_null(r.get("is_current")) and int(r.get("is_current")) == 1:
                current_idx = idx
                break

        if current_idx is None:
            # No current row -> insert new current version
            rows.append(
                {
                    "acct_id": acct_id,
                    "email": s_email,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )
            continue

        c = rows[current_idx]
        c_tier = c.get("tier")
        c_email = c.get("email")

        tier_changed = _not_equal(c_tier, s_tier)
        email_changed = _not_equal(c_email, s_email)

        if tier_changed:
            # expire old current row
            rows[current_idx]["eff_end_date"] = s_update_date
            rows[current_idx]["is_current"] = 0
            # insert new current version
            rows.append(
                {
                    "acct_id": acct_id,
                    "email": s_email,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
            )

        if email_changed:
            # retro-overwrite email across ALL rows of this acct_id
            for r in rows:
                if r.get("acct_id") == acct_id:
                    r["email"] = s_email

    # ---------------------------------------------------------------
    # Build output DataFrame
    # ---------------------------------------------------------------
    out = pd.DataFrame(rows, columns=dim_cols)

    return {"dim_acct_out": out}
